<?php /** @var array $f @var array $lines */ ?>
<pre class="codebox tall" id="log-lines"<?= $f['auto'] !== '' ? ' hx-get="' . e(url('log', $f + ['fragment' => 'lines'])) . '" hx-trigger="every 5s" hx-swap="outerHTML"' : '' ?>><?php foreach ($lines as $l): ?><span<?= $f['hl'] !== '' && preg_match('/error|failed/i', $l) ? ' class="err"' : '' ?>><?= e($l) ?></span><?php endforeach ?><?php if ($lines === []): ?><span class="dim"><?= e(t($f['q'] !== '' ? 'log.no_matching' : 'log.no_lines')) ?></span><?php endif ?></pre>
